// one short vocoder pass on silent codes. it only keeps the clocks up, and it runs only while no
// stream is queued or generating, so it never holds real speech up
static void prewake_step(BreezeModel & model, MimiCodec & codec, GenScheduler & sched) {
    constexpr int frames = 4; // about the work of an early chunk
    const bool ran = sched.exec_if_idle([&] {
        std::vector<int> codes((size_t) frames * model.cfg.num_codebooks, 0);
        codec.decode(codes, frames);
    });
    if (!ran) std::this_thread::sleep_for(std::chrono::milliseconds(5));
}

static void finish_prewake(WsConn & conn, Session & s, const char * reason) {
    if (!s.prewake) return;
