             "\"ttft_ms\":%.3f,\"first_audio_ms\":%.3f,\"prompt_ms\":%.3f,"
             "\"prefill_ms\":%.3f,\"vocoder_ms\":%.3f,\"flushes\":%d,"
             "\"reference_cache_hits\":%d,\"reference_cache_misses\":%d,"
             "\"reference_cache_reused_tokens\":%d,\"reference_cache_prefill_ms\":%.3f",
             t.first_token, t.first_audio, t.prompt, t.prefill, t.vocoder, t.flushes,
             t.reference_cache_hits, t.reference_cache_misses, t.reference_cache_reused_tokens,
             t.reference_cache_prefill);
    std::string out = head;
    out += ",\"generation_s\":" + std::to_string(elapsed) + ",\"audio_s\":" + std::to_string(sent / 24000.0);
    out += ",\"preceding_frames\":" + std::to_string(t.preceding_frames) +
           ",\"preceding_tokens\":" + std::to_string(t.preceding_tokens);
    out += ",\"chunks\":[";
    for (size_t i = 0; i < t.flush_timings.size(); ++i) {
        const auto & f = t.flush_timings[i];
        char item[256];
        snprintf(item, sizeof item,
                 "%s{\"start_frame\":%d,\"audio_frames\":%d,\"context_frames\":%d,"
                 "\"decode_ms\":%.3f,\"ready_ms\":%.3f}",
                 i ? "," : "", f.start_frame, f.audio_frames, f.context_frames, f.decode_ms, f.ready_ms);
