static int reference_prefix_token_count(BreezeModel & m, const ChunkRef & ref) {
    if (ref.codes.empty() || ref.text.empty() || ref.n_frames <= 0) return 0;
    return (int) m.tok.encode("[S0]" + ref.text, true).size() + ref.n_frames + 1;
}

static std::vector<Seg> build_reference_prefix(BreezeModel & m, const ChunkRef & ref) {
    std::vector<Seg> segs;
    segs.push_back(text_seg(m, "[S0]" + ref.text));
    Seg audio;
    audio.is_text = false;
    audio.codes = ref.codes;
    audio.n_frames = ref.n_frames;
    audio.eos = true;
    segs.push_back(std::move(audio));
    return segs;
}

static int reference_tail_token_count(BreezeModel & m, const GenRequest & req,
                                      const std::string & text, bool cond) {
    const std::string tail = cond ? "[S0]<ins_bos>" + req.instruction + "<ins_eos>" + text
                                  : "[S0]" + text;
    return (int) m.tok.encode(tail, true).size();
}

static void rewind_prefix(BackboneState & st, int prefix_tokens) {
    st.pos = prefix_tokens;
    st.kv.len = prefix_tokens;
}

static bool reference_cache_matches(const ReferencePrefixCache & cache, const ChunkRef & ref,
                                    bool use_cfg, int prefix_tokens, int capacity) {
    return cache.cond && cache.cfg == use_cfg && cache.ref_text == ref.text &&
           cache.ref_codes == ref.codes && cache.ref_frames == ref.n_frames &&
           cache.prefix_tokens == prefix_tokens && cache.capacity >= capacity &&
           (!use_cfg || cache.uncond);
}

static bool prepare_reference_cache(BreezeModel & m, const ChunkRef & ref, bool use_cfg,
                                    int prefix_tokens, int capacity,
                                    const std::vector<float> * prefix_emb, GenTimings & tm) {
    auto & cache = m.reference_cache;
    if (reference_cache_matches(cache, ref, use_cfg, prefix_tokens, capacity)) {
        rewind_prefix(*cache.cond, prefix_tokens);
        if (use_cfg) rewind_prefix(*cache.uncond, prefix_tokens);
        tm.reference_cache_hit = true;
        tm.reference_cache_hits++;
        tm.reference_cache_prefix_tokens += prefix_tokens;
        tm.reference_cache_reused_tokens += prefix_tokens;
        return true;
    }
    if (!prefix_emb || prefix_emb->empty()) return false;

    cache.clear();
    auto cond = std::make_unique<BackboneState>();
    auto uncond = use_cfg ? std::make_unique<BackboneState>() : nullptr;
    cond->init(m, capacity);
    if (use_cfg) uncond->init(m, capacity);

    const auto t0 = std::chrono::steady_clock::now();
    backbone_run(m, *cond, *prefix_emb, prefix_tokens);
    if (use_cfg) backbone_run(m, *uncond, *prefix_emb, prefix_tokens);
    tm.reference_cache_prefill +=
        std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();

    cache.cond = std::move(cond);
    cache.uncond = std::move(uncond);
    cache.ref_text = ref.text;
    cache.ref_codes = ref.codes;
    cache.ref_frames = ref.n_frames;
    cache.prefix_tokens = prefix_tokens;
    cache.capacity = capacity;
    cache.cfg = use_cfg;
    rewind_prefix(*cache.cond, prefix_tokens);
    if (use_cfg) rewind_prefix(*cache.uncond, prefix_tokens);
    tm.reference_cache_misses++;
    tm.reference_cache_prefix_tokens += prefix_tokens;
    return true;
}


