// borrows the model's reference prefix states when this request opted in and they fit
bool SpeechJob::use_reference_cache(bool has_ref, int preceding_tokens) {
    auto & cache = m.reference_cache;
    // another stream in the same batch is stepping the cached states, so this one prefills fully
    if (cache.in_use) return false;
    if (!req.cache_reference_prefix || !has_ref) {
        cache.clear();
        return false;
    }
    prefix_tokens = reference_prefix_token_count(m, ref);
    const int tail_c_tokens = reference_tail_token_count(m, req, text, true);
    const int tail_u_tokens = use_cfg ? reference_tail_token_count(m, req, text, false) : 0;
    const long long requested = (long long) prefix_tokens + preceding_tokens +
                                std::max(tail_c_tokens, tail_u_tokens) + max_new + 8;
    if (prefix_tokens <= 0 || prefix_tokens > kMaxReferencePrefixTokens || requested > kMaxReferenceCacheTokens) {
        cache.clear();
        return false;
    }
    // a small token bucket on top, so ordinary text-length changes reuse the voice
    const int capacity = (int) std::min((long long) kMaxReferenceCacheTokens,
                                       ((requested + std::max(0, kRecentMaxTokens - preceding_tokens) + 127) / 128) * 128);
    const bool match = reference_cache_matches(cache, ref, use_cfg, prefix_tokens, capacity);
    std::vector<float> prefix_emb;
    if (!match) {
        const auto t0 = std::chrono::steady_clock::now();
        int assembled = 0;
        prefix_emb = assemble(m, build_reference_prefix(m, ref), assembled);
        tm.prompt += ms_since(t0);
        if (assembled != prefix_tokens) prefix_emb.clear();
    }
    if (!prepare_reference_cache(m, ref, use_cfg, prefix_tokens, capacity, match ? nullptr : &prefix_emb, tm))
        return false;
    cache.in_use = true;
    return true;
}

